    checks: ['闭合曲面的净通量由什么决定？', '外部电荷会影响净通量吗？', '电场为零处电通量一定为零吗？'],
    summary: '电通量描述电场穿过曲面；闭合曲面的净通量只由内部净电荷决定，这就是高斯定律。',
